import{_ as a,o as t,c as o,a0 as r}from"./chunks/framework.BztkuPcJ.js";const h=JSON.parse('{"title":"Sección 1: La Bala Trazadora y el Enrutamiento de las Skills","description":"","frontmatter":{},"headers":[],"relativePath":"journey/tracer-bullet.md","filePath":"journey/tracer-bullet.md"}'),n={name:"journey/tracer-bullet.md"};function s(i,e,l,d,c,p){return t(),o("div",null,[...e[0]||(e[0]=[r(`<h1 id="seccion-1-la-bala-trazadora-y-el-enrutamiento-de-las-skills" tabindex="-1">Sección 1: La Bala Trazadora y el Enrutamiento de las Skills <a class="header-anchor" href="#seccion-1-la-bala-trazadora-y-el-enrutamiento-de-las-skills" aria-label="Permalink to &quot;Sección 1: La Bala Trazadora y el Enrutamiento de las Skills&quot;">​</a></h1><h2 id="contexto-del-proyecto" tabindex="-1">Contexto del proyecto <a class="header-anchor" href="#contexto-del-proyecto" aria-label="Permalink to &quot;Contexto del proyecto&quot;">​</a></h2><p>VoiceLoop nace del <a href="https://github.com/rox651/proyecto-ingenieria-software/blob/main/CLIENT_BRIEF.md" target="_blank" rel="noreferrer">Client Brief</a>: un loop <code>Mic → STT → LLM → TTS → Altavoz</code> en Python puro, sin Pipecat/LiveKit, con panel web y API. El desarrollo se ejecutó con <strong>Cursor Agent</strong> en lugar de Claude Code, reutilizando el flujo <a href="https://www.aihero.dev/running-your-afk-agent-a9l1u" target="_blank" rel="noreferrer">Running Your AFK Agent</a>.</p><hr><h2 id="grill-me-refinando-asunciones-antes-del-codigo" tabindex="-1">grill-me: refinando asunciones antes del código <a class="header-anchor" href="#grill-me-refinando-asunciones-antes-del-codigo" aria-label="Permalink to &quot;grill-me: refinando asunciones antes del código&quot;">​</a></h2><p>En el curso se recomienda la skill <strong>grill-me</strong> para tensionar el diseño. En nuestro flujo con Cursor, el equivalente fue una sesión de exploración estructurada <strong>antes del scaffold</strong>:</p><table tabindex="0"><thead><tr><th>Asunción inicial</th><th>Pregunta “grill”</th><th>Refinamiento</th></tr></thead><tbody><tr><td>“Necesito Pipecat desde el día 1”</td><td>¿Qué capa quieres entender realmente?</td><td>Python asyncio puro; frameworks como referencia, no dependencia</td></tr><tr><td>“Un solo script de 500 líneas”</td><td>¿Cómo testeas sin micrófono en CI?</td><td>Protocolos + stubs + factory <code>stub</code>/<code>live</code></td></tr><tr><td>“Frontend React inmediato”</td><td>¿Cuál es el tracer mínimo de UI?</td><td>HTML/JS + REST; WebSocket en issue posterior</td></tr><tr><td>“Whisper en GPU”</td><td>¿Qué corre en la laptop del curso?</td><td><code>faster-whisper</code> tiny/int8, opcional en extras</td></tr></tbody></table><p>El <strong>árbol de diseño</strong> resultante:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>VoiceLoop</span></span>
<span class="line"><span>├── Core asyncio (pipeline)</span></span>
<span class="line"><span>├── Protocolos intercambiables (STT, LLM, TTS, I/O)</span></span>
<span class="line"><span>├── Factory de composición</span></span>
<span class="line"><span>├── API FastAPI (control plane)</span></span>
<span class="line"><span>└── Dashboard (observabilidad)</span></span></code></pre></div><p>Este árbol se materializó en <code>issues/001–009</code> como <strong>vertical slices</strong> independientes.</p><hr><h2 id="la-bala-trazadora-tracer-bullet" tabindex="-1">La Bala Trazadora (Tracer Bullet) <a class="header-anchor" href="#la-bala-trazadora-tracer-bullet" aria-label="Permalink to &quot;La Bala Trazadora (Tracer Bullet)&quot;">​</a></h2><p>Ousterhout no usa el término “tracer bullet” (viene de <em>The Pragmatic Programmer</em>), pero el curso lo alinea con <strong>reducir riesgo temprano</strong> construyendo un camino end-to-end delgado.</p><h3 id="primera-bala-pipeline-stub-tarea-1" tabindex="-1">Primera bala: pipeline stub (Tarea 1) <a class="header-anchor" href="#primera-bala-pipeline-stub-tarea-1" aria-label="Permalink to &quot;Primera bala: pipeline stub (Tarea 1)&quot;">​</a></h3><p>El primer tracer fue el <strong>loop completo con stubs</strong>:</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Firma pública mínima — oculta 5 etapas</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">result </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> pipeline.run_turn()</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># → TurnResult(user_text, assistant_text)</span></span></code></pre></div><p>Esto validó: asyncio, historial, tests, API <code>/turn</code>, dashboard estático.</p><h3 id="segunda-bala-issue-de-mayor-incertidumbre-—-003-llm" tabindex="-1">Segunda bala: issue de mayor incertidumbre — <code>#003</code> LLM <a class="header-anchor" href="#segunda-bala-issue-de-mayor-incertidumbre-—-003-llm" aria-label="Permalink to &quot;Segunda bala: issue de mayor incertidumbre — \`#003\` LLM&quot;">​</a></h3><p>Tras CI (<code>#008</code>), atacamos <strong><code>#003</code> OpenAI-compatible LLM</strong> porque:</p><ol><li>Introduce <strong>I/O de red</strong> asíncrona (httpx) — primer fallo real fuera del proceso.</li><li>Define el <strong>contrato conversacional</strong> (system prompt, historial) que STT/TTS deben respetar.</li><li>Desbloquea <code>#007</code> WebSocket (eventos <code>transcript</code> / <code>response</code>).</li></ol><p>Ralph ejecutó TDD: test con <code>MockTransport</code> → implementación mínima → commit <code>feat(#003)</code>.</p><h3 id="tercera-bala-006-colas-asyncio" tabindex="-1">Tercera bala: <code>#006</code> colas asyncio <a class="header-anchor" href="#tercera-bala-006-colas-asyncio" aria-label="Permalink to &quot;Tercera bala: \`#006\` colas asyncio&quot;">​</a></h3><p>El issue más arriesgado arquitectónicamente fue <strong><code>#006</code> streaming con <code>asyncio.Queue</code></strong>: refactor del orquestador sin romper <code>/turn</code>. Se validó con 23 tests incluyendo E2E.</p><hr><h2 id="enrutamiento-de-skills" tabindex="-1">Enrutamiento de Skills <a class="header-anchor" href="#enrutamiento-de-skills" aria-label="Permalink to &quot;Enrutamiento de Skills&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Skill</th><th>Cuándo</th><th>Efecto</th></tr></thead><tbody><tr><td><code>/tdd</code></td><td>Cada issue Ralph</td><td>Red-Green-Refactor; tests como contrato</td></tr><tr><td><code>/handoff</code></td><td>Tras 2–3 issues</td><td><code>handoffs.md</code> — purga ruido de contexto</td></tr><tr><td><code>/improve-codebase-architecture</code></td><td>Mid-sprint</td><td><code>factory.py</code> — ver <a href="./retrospective.html">Sección 3</a></td></tr><tr><td><code>ralph/once.sh &lt;ID&gt;</code></td><td>Siguiente ticket</td><td>Respeta <code>blocked_by</code> en frontmatter</td></tr></tbody></table><h3 id="orden-ralph-ejecutado" tabindex="-1">Orden Ralph ejecutado <a class="header-anchor" href="#orden-ralph-ejecutado" aria-label="Permalink to &quot;Orden Ralph ejecutado&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#008 CI → #003 LLM → #001 mic → [checkpoint] → #002 #004 #005 #006 #007 #009</span></span></code></pre></div><p>Prioridad explícita en <code>ralph/prompt.md</code>: bugfix → infra → tracer → feature.</p><hr><h2 id="leccion" tabindex="-1">Lección <a class="header-anchor" href="#leccion" aria-label="Permalink to &quot;Lección&quot;">​</a></h2><p>La bala trazadora no fue “el micrófono” primero, sino <strong>el contrato del loop</strong> (stub) y luego <strong>el LLM</strong> (incertidumbre externa). Eso evitó optimizar audio antes de saber si la conversación funcionaba — coherente con minimizar <strong>change amplification</strong> temprana (Ousterhout, cap. 1).</p><p><strong>Siguiente:</strong> <a href="./anatomy.html">Anatomía de la Complejidad →</a></p>`,33)])])}const m=a(n,[["render",s]]);export{h as __pageData,m as default};
